typedef struct {
  int coins;              /* 0..99999 */
  int xp;                 /* total xp, level derived (levels.json) */
  int amb_cd;             /* ambush countdown, 1/30 s of walking; 0 = roll a new one */
  int amb_walk;           /* total walking time since new game, 1/30 s (tutorial warm-up) */
  int gang_loot;          /* coins the last ambush took, 50% recoverable on the next win */
  unsigned short amb_won, amb_lost;
  unsigned char amb_streak, amb_first_done, pad[2];
  unsigned char arena[8]; /* per arena (arenas.json order): bit7 found, bits 3-6 clears (0..15), bits 0-2 rung (0..4) */
  unsigned int bought[2]; /* shops.json limited[].bit, 64 one-time purchases */
  unsigned int eco_bits;  /* bit0 intro seen, bit1 gang truce, bit2 level-cap banner seen */
} Economy;   /* 52 bytes */
